create or replace function app.register_finance_adjustment_evidence(p_path text,p_original_filename text,p_mime_type text,p_byte_size bigint) returns uuid language plpgsql security definer set search_path='' as $$
declare v_id uuid;v_uid uuid:=auth.uid();v_obj storage.objects%rowtype;v_size bigint;v_mime text;
begin if v_uid is null or not app.has_permission('finance_expenses.record')then raise exception 'Missing permission: finance_expenses.record' using errcode='42501';end if;if p_path not like 'finance/adjustments/%'then raise exception 'Invalid finance adjustment evidence path.' using errcode='23514';end if;if lower(coalesce(p_mime_type,''))not in('application/pdf','image/jpeg','image/png','image/webp')then raise exception 'Adjustment evidence must be PDF, JPEG, PNG, or WEBP.' using errcode='23514';end if;if p_byte_size<=0 or p_byte_size>10485760 then raise exception 'Adjustment evidence must be 1 byte to 10 MB.' using errcode='23514';end if;select * into v_obj from storage.objects where bucket_id='company-documents'and name=p_path and owner_id=v_uid::text;if not found then raise exception 'Uploaded adjustment evidence object was not found.' using errcode='P0002';end if;v_size:=nullif(v_obj.metadata->>'size','')::bigint;v_mime:=lower(coalesce(v_obj.metadata->>'mimetype',''));if v_size is not null and v_size<>p_byte_size then raise exception 'Uploaded object size does not match registration.' using errcode='23514';end if;if v_mime<>''and v_mime<>lower(p_mime_type)then raise exception 'Uploaded object MIME type does not match registration.' using errcode='23514';end if;insert into public.media_assets(bucket,path,original_filename,mime_type,byte_size,visibility,uploaded_by,finalized_at)values('company-documents',p_path,btrim(p_original_filename),lower(p_mime_type),coalesce(v_size,p_byte_size),'restricted',v_uid,now())returning id into v_id;return v_id;end $$;
revoke all on function app.register_finance_adjustment_evidence(text,text,text,bigint) from public,anon;grant execute on function app.register_finance_adjustment_evidence(text,text,text,bigint) to authenticated,service_role;